Dst_Device_Type dstcrypt_get_device_type(void) 
{
  if(dstcrypt_init_nvfs())
    {
      return dstcrypt_nvfs_entry.device_type ;
    }
  else
    {
      return DST_NOT_DEFINE ;
    }
}
